    /// was, and writes whether any had that uuid to `out_replaced`. If none
    /// did, nothing changes.
    ///
    /// C: `otio_ext_ori_replace_commands`
    public static func replaceCommands(_ clip: SerializableObject, uuid: String, commandsJSON: String) throws -> Bool {
        let at = locate(clip)
        return try withExtendedLifetime(at.arena) { () -> Bool in
            return try uuid.withCString { (cUUID: UnsafePointer<CChar>) -> Bool in
                return try commandsJSON.withCString { (cCommandsJSON: UnsafePointer<CChar>) -> Bool in
                    let cClip = try requireHere(at, clip)
                    var outReplaced = false
                    var cError = OtioBuffer()
                    defer { otio_buffer_free(cError) }
                    let status = otio_ext_ori_replace_commands(at.pointer, cClip, cUUID, cCommandsJSON, &outReplaced, &cError)
                    try check(status, cError)
                    return outReplaced
                }
            }
        }
    }

    /// Sends a stroke in progress to everyone in the sync session `session`:
    /// `partial_json` is ORI's `PARTIAL` payload, an object with `clip_guid`,
    /// `frame`, `fps` and `events`, the commands drawn so far. Peers show it
    /// and never store it. A newer one not yet sent replaces it.
    ///
    /// Furnace cannot relay it yet, and refuses it with `Status.unsupported`
    /// when it is about to be sent.
    ///
    /// C: `otio_ext_ori_send_partial`
    public static func sendPartial(_ session: UInt64, partialJSON: String) throws {
        return try partialJSON.withCString { (cPartialJSON: UnsafePointer<CChar>) -> Void in
            var cError = OtioBuffer()
            defer { otio_buffer_free(cError) }
            let status = otio_ext_ori_send_partial(session, cPartialJSON, &cError)
            try check(status, cError)
        }
    }

    /// Replaces all of `clip`'s commands with those in `commands_json`, as
    /// ORI's `REPLACE_ANNOTATION_COMMANDS` does. An empty list, `[]`, clears
    /// it.
    ///
    /// C: `otio_ext_ori_set_commands`
    public static func setCommands(_ clip: SerializableObject, commandsJSON: String) throws {
        let at = locate(clip)
        return try withExtendedLifetime(at.arena) { () -> Void in
            return try commandsJSON.withCString { (cCommandsJSON: UnsafePointer<CChar>) -> Void in
                let cClip = try requireHere(at, clip)
                var cError = OtioBuffer()
                defer { otio_buffer_free(cError) }
                let status = otio_ext_ori_set_commands(at.pointer, cClip, cCommandsJSON, &cError)
                try check(status, cError)
            }
        }
    }

    /// Writes the current time in ISO 8601, for a command's `timestamp`, to
    /// `out_timestamp`.
    ///
    /// C: `otio_ext_ori_timestamp_now`
    public static func timestampNow() throws -> String {
        var outTimestamp = OtioBuffer()
        var cError = OtioBuffer()
        defer { otio_buffer_free(cError) }
        let status = otio_ext_ori_timestamp_now(&outTimestamp, &cError)
        try check(status, cError)
        defer { otio_buffer_free(outTimestamp) }
        return swiftText(outTimestamp)
    }
}
